import urllib.request
import json

token = "13e75dd484c1e398ea8545aa943dd834:"

req = urllib.request.Request(
    "https://api.fleetcomplete.com/graphql",
    headers={
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
        "fleetid": "abb3c44d-0588-486d-9e49-441d9639727c",
        "userid": "f436a0d5-fa20-42ab-b272-15cf68164a1b"
    },
    data=json.dumps({"query": "query { getVehicles { id name latestData { gps { latitude } } } }"}).encode('utf-8')
)
try:
    res = urllib.request.urlopen(req)
    print(res.read().decode('utf-8'))
except Exception as e:
    print(e)
